public enum SignalNativeError {

    
    
    case Protocol(message: String)
    
    case Base64(message: String)
    
    case Utf8(message: String)
    
    case InvalidDeviceId(message: String)
    
    case Storage(message: String)
    
    case InvalidMasterKeyLength(message: String)
    
    /**
     * The peer's identity key doesn't match what we last saw for them
     * (`FileIdentityKeyStore::is_trusted_identity` in store.rs, trust-on-
     * first-use) — either their app reinstalled and generated a fresh
     * identity, or a MITM is presenting a different key. Kept as its own
     * variant (not folded into `Protocol`) so the app can show a specific
     * "this contact's security key changed" message instead of a generic
     * decrypt-failed error — the equivalent of Signal's safety number
     * change warning. Callers must not silently retry past this.
     */
    case UntrustedIdentity(message: String)
    
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeSignalNativeError: FfiConverterRustBuffer {
    typealias SwiftType = SignalNativeError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> SignalNativeError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Protocol(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .Base64(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .Utf8(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 4: return .InvalidDeviceId(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 5: return .Storage(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 6: return .InvalidMasterKeyLength(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 7: return .UntrustedIdentity(
            message: try FfiConverterString.read(from: &buf)
        )
        

        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: SignalNativeError, into buf: inout [UInt8]) {
        switch value {

        

        
        case .Protocol(_ /* message is ignored*/):
            writeInt(&buf, Int32(1))
        case .Base64(_ /* message is ignored*/):
            writeInt(&buf, Int32(2))
        case .Utf8(_ /* message is ignored*/):
            writeInt(&buf, Int32(3))
        case .InvalidDeviceId(_ /* message is ignored*/):
            writeInt(&buf, Int32(4))
        case .Storage(_ /* message is ignored*/):
            writeInt(&buf, Int32(5))
        case .InvalidMasterKeyLength(_ /* message is ignored*/):
            writeInt(&buf, Int32(6))
        case .UntrustedIdentity(_ /* message is ignored*/):
            writeInt(&buf, Int32(7))

        
        }
    }
}


